/** A connection entry with sub-resource accessor methods. Response data properties are deeply readonly. */
export type HydratedConnection<T> = DeepReadonly<T> & ConnectionSubResources;

// ---------------------------------------------------------------------------
// ConnectionsResource
// ---------------------------------------------------------------------------

/** @internal Attach sub-resource accessors to a connection entry. */
function _hydrateConnection<T extends object>(
  entry: T,
  resource: ConnectionsResource,
): HydratedConnection<T> {
  return Object.assign(entry, {
    grants: {
      list: (query?: ListConnectionGrantsQuery) =>
        resource.listGrants((entry as any).connectionId, query),
      listAll: (query?: ListConnectionGrantsQuery) =>
        resource.listGrantsAll((entry as any).connectionId, query),
      create: (body: CreateConnectionGrantBody) =>
        resource.createGrant((entry as any).connectionId, body),
    },
    lookup: (body: LookupConnectionBody) =>
      resource.lookup((entry as any).connectionId, body),
    updateDeprecated: (body: UpdateConnectionDeprecatedBody) =>
      resource.updateDeprecated((entry as any).connectionId, body),
    postDbtArtifacts: (body: PostConnectionDbtArtifactsBody) =>
      resource.postDbtArtifacts((entry as any).connectionId, body),
    syncPath: (body: SyncConnectionPathBody, query?: SyncConnectionPathQuery) =>
      resource.syncPath((entry as any).connectionId, body, query),
    test: () => resource.test((entry as any).connectionId),
  }) as HydratedConnection<T>;
}

