  async list(
    query?: ListConnectionsQuery,
  ): Promise<HydratePage<ListConnectionsResponse, ConnectionSubResources>> {
    const { data, error, response } = await this.client.GET('/v2/connections', {
      params: { query },
    });
    if (error) throw new SigmaApiError(error, response);
    const result = data! as any;
    if (Array.isArray(result)) {
      return result.map((e: any) => _hydrateConnection(e, this)) as any;
    }
    if (result.entries && Array.isArray(result.entries)) {
      result.entries = result.entries.map((e: any) =>
        _hydrateConnection(e, this),
      );
    }
    return result;
  }

